import pytest
from isort.output import sorted_imports
from unittest.mock import MagicMock
import itertools

class MockParsedContent:
    def __init__(self, line_separator="\n", imports=None, lines_without_imports=None, import_index=-1):
        self.line_separator = line_separator
        self.imports = imports if imports else {"FUTURE": {"straight": {}, "from": {}}}
        self.lines_without_imports = lines_without_imports if lines_without_imports else []
        self.import_index = import_index

@pytest.fixture
def parsed_content():
    return MockParsedContent()

def test_sorted_imports_no_imports(parsed_content):
    # Test case with no imports (code should return just a newline).
    result = sorted_imports(parsed_content)
    assert result == "\n"

def test_sorted_imports_simple(parsed_content):
    # Test case with basic imports.
    parsed_content.lines_without_imports = ["print('Hello World')"]
    parsed_content.imports = {
        "DEFAULT": {
            "straight": {"module_a": {}, "module_b": {}},
            "from": {}
        }
    }
    parsed_content.import_index = 0
    result = sorted_imports(parsed_content)
    assert "import module_a" in result
    assert "import module_b" in result

def test_sorted_imports_with_sections(parsed_content):
    # Test case with imports in different sections.
    parsed_content.lines_without_imports = ["print('Goodbye World')"]
    parsed_content.imports = {
        "FUTURE": {
            "straight": {},
            "from": {"module_c": {"*": []}}
        },
        "DEFAULT": {
            "straight": {"module_a": {}, "module_b": {}},
            "from": {"module_d": {"*": []}}
        }
    }
    parsed_content.import_index = 0
    result = sorted_imports(parsed_content)
    assert "import module_a" in result
    assert "import module_b" in result
    assert "from module_d import *" in result

def test_sorted_imports_with_empty_remove_imports(parsed_content):
    # Test case simulating a configuration with empty remove_imports.
    parsed_content.lines_without_imports = ["print('Hello World')"]
    mock_config = MagicMock()
    mock_config.remove_imports = []  # No imports to remove
    parsed_content.imports = {
        "DEFAULT": {
            "straight": {"module_a": {}, "module_b": {}}
        }
    }
    parsed_content.import_index = 0
    result = sorted_imports(parsed_content)
    assert "import module_a" in result
    assert "import module_b" in result

def test_sorted_imports_with_remove_imports(parsed_content):
    # Test case where we remove specified imports.
    parsed_content.lines_without_imports = ["print('Hello World')"]
    mock_config = MagicMock()
    mock_config.remove_imports = ["module_b"]  # Simulating removal of module_b
    parsed_content.imports = {
        "DEFAULT": {
            "straight": {"module_a": {}, "module_b": {}}
        }
    }
    parsed_content.import_index = 0
    result = sorted_imports(parsed_content)
    assert "import module_a" in result
    assert "import module_b" not in result  # module_b should be removed

def test_sorted_imports_star_first(parsed_content):
    # Test case should configure to ensure star imports come first
    parsed_content.lines_without_imports = ["print('Hello World')"]
    parsed_content.imports = {
        "DEFAULT": {
            "straight": {},
            "from": {"module_a": {"*": []}, "module_b": {}}
        }
    }
    parsed_content.import_index = 0
    result = sorted_imports(parsed_content)
    assert "from module_a import *" in result
    assert "import module_b" in result
